python - <<'PY'
from more_itertools import interleave_evenly, sliced, numeric_range
from decimal import Decimal
from fractions import Fraction
from datetime import datetime, timedelta
from itertools import product

for inputs in ([], [[], []], [[], [1, 2], []], [[1], [], [2, 3]]):
    for lengths in (None, list(map(len, inputs))):
        result = list(interleave_evenly(inputs, lengths=lengths))
        assert sorted(result) == sorted(x for seq in inputs for x in seq)
for strict in (False, True):
    for seq in ([], [1, 2, 3]):
        try:
            sliced(seq, -1, strict=strict)
        except ValueError:
            pass
        else:
            raise AssertionError('negative size accepted')
    assert list(sliced([1, 2], 0, strict=strict)) == []

for start, stop, step in product(range(-4, 5), range(-4, 5), (-3, -1, 1, 3)):
    nr = numeric_range(start, stop, step)
    assert list(reversed(nr)) == list(range(start, stop, step))[::-1]
for kind in (float, Decimal, Fraction):
    for start, stop, step in product(('-0.3', '0', '0.1', '1'), repeat=3):
        start, stop, step = map(kind, (start, stop, step))
        if not step:
            continue
        nr = numeric_range(start, stop, step)
        assert list(reversed(nr)) == list(nr)[::-1], (start, stop, step)
for start, stop, step in (
    (datetime.min, datetime.min + timedelta(days=3), timedelta(days=1)),
    (datetime.max, datetime.max - timedelta(days=3), -timedelta(days=1)),
    (datetime.min, datetime.min, timedelta(days=1)),
):
    nr = numeric_range(start, stop, step)
    assert list(reversed(nr)) == list(nr)[::-1]
print('All targeted regression checks passed')
